document.addEventListener("DOMContentLoaded",init);let owner=null;let hub=null;let inventory=[];let wizardId="";let busy=false;const $=id=>document.getElementById(id);const call=(action,payload)=>Api.post(action,Object.assign({token:Auth.getToken()},payload||{}));const STATUS_TEXT={applied:"Applied",duplicate:"Already received",needs_mapping:"Needs matching",conflict:"Needs a decision",failed:"Failed",pending_parent:"Waiting for its sale",rejected:"Rejected",echo:"Ignored (our own change)",ignored:"Ignored",stale:"Older version ignored",dead:"Gave up",stock_review:"Stock count to review"};const DISPLAY_CLASS={Connected:"ok","Attention required":"warn",Paused:"muted","Waiting for first signal":"muted","Waiting for first sync":"muted"};async function init(){owner=await Auth.guardOwnerAuth();if(!owner)return;$("store-name-label").textContent=shortStoreName(owner.storeName);$("hub-add").addEventListener("click",openWizard);$("wiz-cancel").addEventListener("click",closeWizard);$("wiz-create").addEventListener("click",createConnection);$("wiz-saved").addEventListener("change",e=>{$("wiz-next").disabled=!e.target.checked});$("wiz-next").addEventListener("click",()=>{show("hub-wiz-2",false);show("hub-wiz-3",true)});$("wiz-check").addEventListener("click",refreshAll);$("wiz-done").addEventListener("click",()=>{closeWizard();refreshAll()});$("act-reload").addEventListener("click",loadEvents);$("act-filter").addEventListener("change",loadEvents);$("act-q").addEventListener("keydown",e=>{if(e.key==="Enter")loadEvents()});$("out-now").addEventListener("click",sendNow);document.querySelectorAll("[data-copy]").forEach(b=>b.addEventListener("click",()=>copyText(b)));await refreshAll()}const show=(id,on)=>$(id).classList.toggle("hidden",!on);function setStatus(msg){$("hub-status").textContent=msg||""}async function refreshAll(){const res=await call("posHubStatus");if(!res.ok){setStatus(res.error||"Could not load. Try again.");return}setStatus("");hub=res;show("hub-off",!res.enabled);show("hub-main",!!res.enabled);if(!res.enabled)return;renderConnections();await loadInventory();await Promise.all([loadMappings(),loadEvents(),loadOutbox()]);if(wizardId&&!$("hub-wiz-3").classList.contains("hidden")){const c=(hub.connections||[]).find(x=>x.connectionId===wizardId);$("wiz-wait").textContent=c&&c.verifiedAt?"Connected. Mwakete received a correctly signed message.":"Waiting for the first message… (nothing is connected until one arrives)"}}async function loadInventory(){const res=await call("getInventory");inventory=res.ok?res.items||[]:[]}function renderConnections(){const list=hub.connections||[];const box=$("hub-connections");const att=$("hub-attention");att.classList.toggle("hidden",!hub.attention);att.textContent=hub.attention?`${hub.attention} item${hub.attention===1?" needs":"s need"} your attention. See Activity below.`:"";if(!list.length){box.innerHTML='<p class="helper-text">Nothing connected yet. Press <strong>Connect a system</strong> to start. You can also use <a href="inventory-sync.html">Import &amp; Sync</a> for a CSV or Google Sheet.</p>'}else{box.innerHTML=list.map(c=>{const cls=DISPLAY_CLASS[c.displayStatus]||"muted";const mine=c.type==="pushApi";return`<article class="hub-card" data-id="${escapeAttr(c.connectionId)}">\n        <header><strong>${escapeHtml(c.name)}</strong> <span class="hub-badge hub-${cls}">${escapeHtml(c.displayStatus)}</span></header>\n        <p class="helper-text">${escapeHtml(c.provider||"")}${c.lastSignalAt?" · last message "+escapeHtml(timeAgo(c.lastSignalAt)):c.lastSyncAt?" · last sync "+escapeHtml(timeAgo(c.lastSyncAt)):""}</p>\n        ${c.lastError?`<p class="form-error">${escapeHtml(c.lastError)}</p>`:""}\n        ${mine&&c.counts?`<p class="helper-text">${c.counts.applied||0} applied · ${c.counts.attention||0} need attention</p>`:""}\n        <p class="helper-text">${(c.capabilities||[]).map(escapeHtml).join(" · ")}</p>\n        <div class="hub-actions">${mine?'<button type="button" class="btn btn-small" data-act="settings">Settings</button>':`<a class="btn btn-small" href="${escapeAttr(c.managedOn||"inventory-sync.html")}">Manage</a>`}</div>\n      </article>`}).join("");box.querySelectorAll('[data-act="settings"]').forEach(b=>b.addEventListener("click",()=>openDetail(b.closest(".hub-card").dataset.id)))}$("hub-connectors").innerHTML=(hub.connectors||[]).map(k=>`<p><strong>${escapeHtml(k.label)}</strong>${k.available?"":" <em>(not set up)</em>"}<br><span class="helper-text">Can: ${(k.capabilities||[]).map(escapeHtml).join(", ")}. Limits: ${(k.limits||[]).map(escapeHtml).join(" ")}</span></p>`).join("")+(hub.pending||[]).map(p=>`<p><strong>${escapeHtml(p.label)}</strong> — <em>not available yet.</em><br><span class="helper-text">${escapeHtml(p.why)}</span></p>`).join("")}function timeAgo(iso){const t=Date.parse(iso);if(!isFinite(t))return"";const m=Math.round((Date.now()-t)/6e4);if(m<1)return"just now";if(m<60)return m+" min ago";if(m<1440)return Math.round(m/60)+" h ago";return Math.round(m/1440)+" days ago"}function openWizard(){wizardId="";$("wiz-name").value="";$("wiz-provider").value="";$("wiz-account").value="";$("wiz-error").textContent="";$("wiz-saved").checked=false;$("wiz-next").disabled=true;show("hub-wiz-1",true);show("hub-wiz-2",false);show("hub-wiz-3",false);show("hub-wizard",true);$("wiz-name").focus()}function closeWizard(){wizardId="";$("wiz-secret").textContent="";show("hub-wizard",false)}async function createConnection(){if(busy)return;busy=true;const busyDone=setButtonBusy($("wiz-create"),"Creating");$("wiz-error").textContent="";const res=await call("createPosConnection",{name:$("wiz-name").value,providerName:$("wiz-provider").value,accountKey:$("wiz-account").value});busy=false;busyDone();if(!res.ok){$("wiz-error").textContent=res.error||"Could not create it.";return}wizardId=res.connectionId;$("wiz-id").textContent=res.connectionId;$("wiz-secret").textContent=res.secret;$("wiz-endpoint").textContent=APP_CONFIG.APPS_SCRIPT_URL;show("hub-wiz-1",false);show("hub-wiz-2",true)}async function copyText(btn){const text=$(btn.dataset.copy).textContent;try{await navigator.clipboard.writeText(text);btn.textContent="Copied"}catch(e){btn.textContent="Select and copy"}setTimeout(()=>{btn.textContent="Copy"},2e3)}function openDetail(id){const c=(hub.connections||[]).find(x=>x.connectionId===id);if(!c)return;const r=c.rules||{};const body=$("hub-detail-body");const locOpts=hub.locations||[];body.innerHTML=`<h3>${escapeHtml(c.name)}</h3>\n    <p class="helper-text">Key ending <code>${escapeHtml(c.keyId||"")}</code>. The secret itself is never shown again.</p>\n    <fieldset><legend>When a sale arrives</legend>\n      <label class="check"><input type="checkbox" id="r-import" ${r.importSales?"checked":""}> Take sold items off my stock</label>\n      <label class="check"><input type="checkbox" id="r-returns" ${r.applyReturns?"checked":""}> Apply refunds and returns</label>\n      <div class="field"><label for="r-restock">Put returned goods back in stock</label>\n        <select id="r-restock"><option value="when_flagged">Only when my system says they are back</option><option value="always">Always</option><option value="never">Never</option></select></div>\n      <div class="field"><label for="r-snap">Stock counts from my system</label>\n        <select id="r-snap"><option value="review">Show me the differences to decide</option><option value="ignore">Ignore them</option></select></div>\n    </fieldset>\n    <fieldset><legend>Send my online orders to my system</legend>\n      <label class="check"><input type="checkbox" id="r-export" ${r.exportOrders?"checked":""}> Send new, paid, cancelled and completed orders</label>\n      <label class="check"><input type="checkbox" id="r-contact" ${r.shareCustomerContact?"checked":""}> Include the customer's name, phone and email (off by default)</label>\n      <div class="field"><label for="r-url">Address that receives them (https only)</label>\n        <input type="url" id="r-url" inputmode="url" placeholder="https://…" value=""><small class="helper-text">${c.webhookUrlSet?"Currently set to "+escapeHtml(c.webhookHost)+". Type a new address to replace it.":"Not set."}</small></div>\n      <button type="button" class="btn btn-small" id="d-test">Send a test</button> <span id="d-test-out" class="helper-text" role="status"></span>\n    </fieldset>\n    ${locOpts.length?`<fieldset><legend>Shops in your system → your locations</legend><p class="helper-text">Without this, sales come off your main stock.</p><div id="d-locmap"></div></fieldset>`:""}\n    <p id="d-error" class="form-error" role="alert"></p>\n    <div class="hub-actions">\n      <button type="button" class="btn btn-primary" id="d-save">Save settings</button>\n      <button type="button" class="btn" id="d-pause">${c.status==="paused"?"Resume":"Pause"}</button>\n      <button type="button" class="btn" id="d-rotate">New secret</button>\n      <button type="button" class="btn btn-danger" id="d-disconnect">Disconnect</button>\n      <button type="button" class="btn" id="d-close">Close</button>\n    </div><div id="d-newsecret"></div>`;$("r-restock").value=r.restock||"when_flagged";$("r-snap").value=r.snapshots||"review";const map=c.locationMap||{};if(locOpts.length){const keys=Object.keys(map);$("d-locmap").innerHTML=(keys.length?keys:[""]).map(k=>`<div class="hub-locrow"><input type="text" class="lm-key" maxlength="80" placeholder="Shop ID in your system" value="${escapeAttr(k)}">\n      <select class="lm-loc"><option value="main">Main stock</option>${locOpts.map(l=>`<option value="${escapeAttr(l.locationId)}"${map[k]===l.locationId?" selected":""}>${escapeHtml(l.name)}</option>`).join("")}</select></div>`).join("")}show("hub-detail",true);$("d-close").addEventListener("click",()=>show("hub-detail",false));$("d-save").addEventListener("click",()=>saveDetail(c));$("d-test").addEventListener("click",()=>testHook(c));$("d-pause").addEventListener("click",()=>changeState(c,c.status==="paused"?"resume":"pause"));$("d-disconnect").addEventListener("click",()=>{if(confirm('Disconnect "'+c.name+'"? It stops receiving sales. Past records are kept.'))changeState(c,"disconnect")});$("d-rotate").addEventListener("click",()=>rotate(c));$("hub-detail").scrollIntoView({behavior:"smooth",block:"start"})}async function saveDetail(c){if(busy)return;busy=true;$("d-error").textContent="";const payload={connectionId:c.connectionId,rules:{importSales:$("r-import").checked,applyReturns:$("r-returns").checked,restock:$("r-restock").value,snapshots:$("r-snap").value,exportOrders:$("r-export").checked,shareCustomerContact:$("r-contact").checked}};const url=$("r-url").value.trim();if(url)payload.webhookUrl=url;const rows=document.querySelectorAll(".hub-locrow");if(rows.length){payload.locationMap={};rows.forEach(row=>{const k=row.querySelector(".lm-key").value.trim();const l=row.querySelector(".lm-loc").value;if(k)payload.locationMap[k]=l})}const res=await call("updatePosConnection",payload);busy=false;if(!res.ok){$("d-error").textContent=res.error||"Could not save.";return}setStatus("Saved.");await refreshAll();openDetail(c.connectionId)}async function testHook(c){$("d-test-out").innerHTML=loadingMessageHtml("Sending");const res=await call("testPosWebhook",{connectionId:c.connectionId});$("d-test-out").textContent=!res.ok?res.error||"Could not send.":res.reachable?"Your system answered. Orders can now be sent.":res.message||"Your system did not accept it.";if(res.ok&&res.reachable)refreshAll()}async function changeState(c,state){const res=await call("setPosConnectionState",{connectionId:c.connectionId,state:state});if(!res.ok){$("d-error").textContent=res.error||"Could not change it.";return}if(state==="disconnect")show("hub-detail",false);await refreshAll();if(state!=="disconnect")openDetail(c.connectionId)}async function rotate(c){if(!confirm("Make a new secret? The old one stops working immediately, so your system must be updated."))return;const res=await call("rotatePosSecret",{connectionId:c.connectionId});if(!res.ok){$("d-error").textContent=res.error||"Could not do that.";return}$("d-newsecret").innerHTML=`<p><strong>New secret (shown once):</strong> <code id="d-sec">${escapeHtml(res.secret)}</code> <button type="button" class="btn btn-small" data-copy="d-sec">Copy</button></p>`;$("d-newsecret").querySelector("[data-copy]").addEventListener("click",e=>copyText(e.target))}async function loadMappings(){const res=await call("listIntegrationMappings",{status:"review"});const box=$("hub-mappings");if(!res.ok){box.innerHTML=`<p class="form-error">${escapeHtml(res.error||"Could not load.")}</p>`;return}const list=res.mappings||[];if(!list.length){box.innerHTML='<p class="helper-text">Nothing to match. Every item that has arrived was matched exactly.</p>';return}const options=inventory.map(i=>`<option value="${escapeAttr(i.variantId)}">${escapeHtml(i.productName||i.name||"")} — ${escapeHtml(i.label||"")}${i.sku?" ("+escapeHtml(i.sku)+")":""}</option>`).join("");box.innerHTML=list.map(m=>`<div class="hub-map" data-id="${escapeAttr(m.mappingId)}" data-conn="${escapeAttr(m.connectionId)}">\n      <div><strong>${escapeHtml(m.label||m.externalSku||m.externalVariantId||m.externalKey)}</strong><br><span class="helper-text">${escapeHtml(m.externalKey)} · ${escapeHtml(m.note||"")}</span></div>\n      <select aria-label="Which of your products is this?"><option value="">Choose your product…</option>${options}</select>\n      <button type="button" class="btn btn-small btn-primary">Match</button></div>`).join("");box.querySelectorAll(".hub-map").forEach(row=>{const m=list.find(x=>x.mappingId===row.dataset.id);row.querySelector("button").addEventListener("click",async()=>{const variantId=row.querySelector("select").value;if(!variantId){setStatus("Choose which of your products it is.");return}const res2=await call("saveIntegrationMapping",{connectionId:m.connectionId,externalVariantId:m.externalVariantId,externalProductId:m.externalProductId,externalSku:m.externalSku,label:m.label,variantId:variantId});setStatus(res2.ok?"Matched. Press Retry on the held sale in Activity to apply it.":res2.error||"Could not save.");if(res2.ok){await loadMappings();await loadEvents()}})})}async function loadEvents(){const f=$("act-filter").value;const res=await call("listIntegrationEvents",{attentionOnly:f==="attention",status:f&&f!=="attention"?f:undefined,q:$("act-q").value.trim(),limit:50});const box=$("hub-events");if(!res.ok){box.innerHTML=`<p class="form-error">${escapeHtml(res.error||"Could not load.")}</p>`;return}const list=res.events||[];if(!list.length){box.innerHTML='<p class="helper-text">Nothing here.</p>';return}box.innerHTML=`<div class="hub-table-wrap"><table class="hub-table"><thead><tr><th>When</th><th>What</th><th>Result</th><th></th></tr></thead><tbody>${list.map(e=>{const attention=["needs_mapping","conflict","failed","pending_parent","dead"].indexOf(e.status)!==-1&&e.recon!=="resolved";return`<tr data-id="${escapeAttr(e.eventId)}"><td>${escapeHtml(timeAgo(e.createdAt))}</td>\n      <td>${escapeHtml(e.direction==="out"?"Sent: ":"")}${escapeHtml(e.type)} <code>${escapeHtml(e.externalId||"")}</code></td>\n      <td><span class="hub-badge hub-${attention?"warn":"ok"}">${escapeHtml(STATUS_TEXT[e.status]||e.status)}</span>${e.recon==="resolved"?' <span class="helper-text">resolved</span>':""}<br><span class="helper-text">${escapeHtml(e.message||"")}</span></td>\n      <td class="hub-actions">${e.retryable?'<button type="button" class="btn btn-small" data-do="retry">Retry</button>':""}${attention?'<button type="button" class="btn btn-small" data-do="acknowledge">Mark handled</button>':""}${e.type==="stock"&&attention?'<button type="button" class="btn btn-small" data-do="accept_external">Use their count</button><button type="button" class="btn btn-small" data-do="keep_mwakete">Keep mine</button>':""}</td></tr>`}).join("")}</tbody></table></div>${res.total>list.length?`<p class="helper-text">Showing ${list.length} of ${res.total}. Narrow the search to see others.</p>`:""}`;box.querySelectorAll("[data-do]").forEach(b=>b.addEventListener("click",async()=>{const id=b.closest("tr").dataset.id;const action=b.dataset.do;if(action==="accept_external"&&!confirm("Change your stock to match their count? This is recorded in your stock history."))return;const busyDone=setButtonBusy(b,"Working");const r=await call("resolveIntegrationEvent",{eventId:id,resolution:action});setStatus(r.ok?r.message||"Done.":r.error||"Could not do that.");await refreshAll()}))}async function loadOutbox(){const res=await call("listIntegrationOutbox",{});const box=$("hub-outbox");if(!res.ok){box.innerHTML="";return}const list=res.items||[];if(!list.length){box.innerHTML='<p class="helper-text">No orders have been sent. Turn on "Send my online orders" in a connection\'s settings, and test the address first.</p>';return}box.innerHTML=`<div class="hub-table-wrap"><table class="hub-table"><thead><tr><th>Order</th><th>Event</th><th>Status</th><th></th></tr></thead><tbody>${list.slice(0,20).map(o=>`<tr data-id="${escapeAttr(o.outboxId)}">\n    <td><code>${escapeHtml(o.orderId)}</code></td><td>${escapeHtml(o.event)}</td>\n    <td><span class="hub-badge hub-${o.status==="sent"?"ok":o.status==="dead"?"warn":"muted"}">${escapeHtml(o.status==="dead"?"Gave up":o.status==="sent"?"Delivered":"Waiting")}</span> ${o.attempts?'<span class="helper-text">'+o.attempts+" tries</span>":""}<br><span class="helper-text">${escapeHtml(o.error||"")}</span></td>\n    <td>${o.status==="dead"?'<button type="button" class="btn btn-small" data-do="retry">Try again</button>':""}</td></tr>`).join("")}</tbody></table></div>`;box.querySelectorAll('[data-do="retry"]').forEach(b=>b.addEventListener("click",async()=>{const r=await call("retryIntegrationOutbox",{outboxId:b.closest("tr").dataset.id});setStatus(r.ok?'Queued. It will go out within the hour, or press "Send waiting messages now".':r.error||"Could not retry.");loadOutbox()}))}async function sendNow(){const busyDone=setButtonBusy($("out-now"),"Sending");const r=await call("sendIntegrationOutboxNow");busyDone();setStatus(r.ok?`Processed ${r.processed||0} message${r.processed===1?"":"s"}.`:r.error||"Could not send.");loadOutbox();loadEvents()}